'use client'
import { useEffect } from 'react'
import { CSS, HTML } from './content'

// Content generated by scripts/sync.py (redacted copy of the private page).
// (single source with the preview and the reference-pack ZIP). ?flat=1 shows every section at once.
const VARS = [
  "--display:var(--font-display),'Arial Black',sans-serif", '--sans:var(--font-sans),system-ui,sans-serif',
  '--mono:var(--font-mono),ui-monospace,monospace', "--thai:var(--font-thai),'Noto Sans Thai',sans-serif",
].join(';')

export default function KhaoHom() {
  useEffect(() => {
    const main = document.querySelector('.kh')
    if (!main || location.search.includes('flat') || !('IntersectionObserver' in window)) return
    main.classList.add('armed')
    const io = new IntersectionObserver(
      (es) => es.forEach((e) => { if (e.isIntersecting) { e.target.classList.add('in'); io.unobserve(e.target) } }),
      { threshold: 0.06 }
    )
    document.querySelectorAll('.reveal').forEach((el) => {
      if (el.getBoundingClientRect().top < innerHeight) el.classList.add('in')
      io.observe(el)
    })
    return () => io.disconnect()
  }, [])

  return (
    <>
      <style dangerouslySetInnerHTML={{ __html: `:root{${VARS}}` + CSS }} />
      <main className="kh" dangerouslySetInnerHTML={{ __html: HTML }} />
    </>
  )
}
